class Solution {
    public int maxResult(int[] nums,int k){
        int[] dp=new int[nums.length];
        dp[0]=nums[0];
        Deque<Integer> deque=new ArrayDeque<>();
        deque.offerLast(0);
        for(int i=1;i<nums.length;i++){
            while(deque.peekFirst()<i-k)deque.pollFirst();
            dp[i]=nums[i]+dp[deque.peekFirst()];
            while(!deque.isEmpty()&&dp[deque.peekLast()]<=dp[i])deque.pollLast();
            deque.offerLast(i);
        }
        return dp[nums.length-1];
    }
}

code.kotlin:
class Solution {
    fun maxResult(nums:IntArray,k:Int):Int{
        val dp=IntArray(nums.size);
        dp[0]=nums[0];
        val deque=java.util.ArrayDeque<Int>();
        deque.addLast(0);
        for(i in 1 until nums.size){
            while(deque.first<i-k)deque.removeFirst();
            dp[i]=nums[i]+dp[deque.first];
            while(deque.isNotEmpty()&&dp[deque.last]<=dp[i])deque.removeLast();
            deque.addLast(i)
        };
        return dp.last()
    }
}

